sys_script.script:
(function executeRule(current, previous /* null when async */) {

    /* ======================================================
       CAMPUSMATCH — AUTO APPROVE PASSED CLAIM
    ====================================================== */


    /* ======================================================
       1. READ VERIFICATION RESULT
    ====================================================== */

    var verificationResult =
        (
            current.getValue(
                'u_verification_result'
            ) || ''
        )
        .toString()
        .trim()
        .toLowerCase();


    /*
     * Only high-confidence Pass claims.
     */
    if (
        verificationResult !==
            'pass'
    ) {

        return;
    }



    /* ======================================================
       2. RUN ONLY WHEN RESULT BECOMES PASS
    ====================================================== */

    if (previous) {

        var previousResult =
            (
                previous.getValue(
                    'u_verification_result'
                ) || ''
            )
            .toString()
            .trim()
            .toLowerCase();


        /*
         * Prevent recursion after our automatic
         * Claim update.
         */
        if (
            previousResult ===
                'pass'
        ) {

            return;
        }
    }



    /* ======================================================
       3. CHECK CURRENT CLAIM STATUS
    ====================================================== */

    var currentStatus =
        (
            current.getValue(
                'claim_status'
            ) || ''
        )
        .toString()
        .trim()
        .toLowerCase();


    if (
        currentStatus ===
            'approved' ||
        currentStatus ===
            'rejected' ||
        currentStatus ===
            'cancelled'
    ) {

        return;
    }



    /* ======================================================
       4. RELOAD CLAIM
    ====================================================== */

    var claim =
        new GlideRecord(
            'x_snc_campusmatch_campusmatch_claim'
        );


    if (
        !claim.get(
            current.getUniqueValue()
        )
    ) {

        gs.error(
            'CampusMatch Auto Approve: Claim could not be reloaded.'
        );

        return;
    }



    /* ======================================================
       5. AUTO APPROVE
    ====================================================== */

    claim.setValue(
        'claim_status',
        'Approved'
    );



    /* ======================================================
       6. VERIFIED BY = SYSTEM ADMINISTRATOR

       IMPORTANT:
       Do NOT use gs.getUserID().
       That would store the claimant as the verifier.
    ====================================================== */

    if (
        claim.isValidField(
            'verified_by'
        )
    ) {

        var systemUser =
            new GlideRecord(
                'sys_user'
            );


        /*
         * Find the ServiceNow admin account.
         */
        systemUser.addQuery(
            'user_name',
            'admin'
        );


        systemUser.setLimit(
            1
        );


        systemUser.query();


        if (
            systemUser.next()
        ) {

            claim.setValue(
                'verified_by',
                systemUser.getUniqueValue()
            );

        }
    }



    /* ======================================================
       7. VERIFIED ON
    ====================================================== */

    if (
        claim.isValidField(
            'verified_on'
        )
    ) {

        claim.setValue(
            'verified_on',
            new GlideDateTime()
        );

    }



    /* ======================================================
       8. UPDATE CLAIM

       Existing Collection Token BR will run because
       we DO NOT disable workflow.
    ====================================================== */

    var claimUpdateId =
        claim.update();


    if (!claimUpdateId) {

        gs.error(
            'CampusMatch Auto Approve: Unable to approve Claim ' +
            current.getUniqueValue()
        );

        return;
    }



    /* ======================================================
       9. CONFIRM RELATED MATCH
    ====================================================== */

    var matchId =
        current.getValue(
            'match'
        );


    if (matchId) {

        var match =
            new GlideRecord(
                'x_snc_campusmatch_campusmatch_match'
            );


        if (
            match.get(
                matchId
            )
        ) {

            match.setValue(
                'status',
                'confirmed'
            );


            match.update();

        }
        else {

            gs.error(
                'CampusMatch Auto Approve: Related Match could not be found: ' +
                matchId
            );

        }
    }


})(current, previous);
